SELECT Site.numsit,Intervention.refcliint,Site.nomsit,Site.typsit,Site.vilsit,Intervention.datint,Intervention.intafact,Intervention.codpan,Intervention.typint,Intervention.nummodres,Intervention.mntfac,Client.nomcli FROM [Client],[Site],[parametre],[Intervention] WHERE (((Intervention.datint) Between [parametre]![datdeb] And [parametre]![datfin]) AND ((Intervention.intafact)=True)) ORDER BY Site.nomsit
